    private void givenAttribute(final Tscalar type, final int cardinality) {
        this.attribute = new Tad();
        this.attribute.setId(ATTRIBUTE);
        this.attribute.setName(ATTRIBUTE);
        this.attribute.setType(type);
        this.attribute.setCardinality(cardinality);
        this.attribute.setRequired(true);
    }

    private void givenRange(final String min, final String max) {
        this.attribute.setMin(min);
        this.attribute.setMax(max);
    }

    private void givenOptions(final String... values) {
        Arrays.stream(values).forEach(value -> {
            final Toption option = new Toption();
            option.setLabel(value);
            option.setValue(value);
            this.attribute.setOption(option);
        });
    }

    private void givenRequired(final boolean required) {
        this.attribute.setRequired(required);
    }

    private void givenProperty(final String key, final Object value) {
        this.properties.put(key, value);
    }

    private void whenValueIsValidated(final Object value) {
        try {
            MetatypeValidator.validateValue(this.attribute, value);
        } catch (final KuraException e) {
            this.occurredException = e;
        }
    }

    private void whenPropertiesAreValidated() {
        try {
            MetatypeValidator.validate(ocd(), this.properties, this.properties);
        } catch (final KuraException e) {
            this.occurredException = e;
        }
    }

    private void whenOnlyValuesAreValidated() {
        try {
            MetatypeValidator.validateValues(ocd(), this.properties);
        } catch (final KuraException e) {
            this.occurredException = e;
        }
    }

    private void thenValueIsAccepted() {
        assertNull(this.occurredException);
    }

    private void thenValueIsRejectedWith(final KuraErrorCode code) {
        assertNotNull(this.occurredException);
        assertEquals(code, this.occurredException.getCode());
    }

    private void thenErrorMessageContains(final String text) {
        assertTrue(this.occurredException.getMessage(), this.occurredException.getMessage().contains(text));
    }

    private void thenErrorMessageDoesNotContain(final String text) {
        assertFalse(this.occurredException.getMessage(), this.occurredException.getMessage().contains(text));
    }

    private Tocd ocd() {
        final Tocd ocd = new Tocd();
        ocd.setId("ocd");
        ocd.addAD(this.attribute);
        return ocd;
    }
